private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int result = 0;
    while (i < 4 && bb.get() == 0) { // Scan the beginning 4 octets for zeros
        ++i;
    }
    if (i == 4) {
        // Two or more consecutive zeros width the first non-zero byte indicates null data
        return -1; // UTF-8 null data can be decoded as empty string
    }
    boolean isValid = false;
    for (int j = 0; j < i; j++) {
        int b = bb.get();
        if ((b & 0xC0) == 0x80) { // Current byte is a continuation byte
            result <<= 6;
            result |= b & 0x3F;
            isValid = true;
        } else {
            if (!isValid) {
                return i; // Scratchpad data, decode as-is
            }
            // Decode multi-octet sequence
            while ((b & 0xC0) == 0x80) {
                b = bb.get();
                result <<= 6;
                result |= b & 0x3F;
            }
            int start = i - j - 1;
            if ((b | (0x30 - ((j + 1) * 6))) >= 0x85 && (b | (0x30 - ((j + 1) * 6))) <= 0xBF) {
                // Full-width Unicode character
                result += 128;
                // Shift the value by 7 bits
                result = result << 7;
            } else {
                // Half-width Unicode character
                result += 64;
            }
            return start;
        }
    }
    if (!isValid) {
        return i; // Scratchpad data, decode as-is
    }
    while ((bb.get() & 0xC0) == 0x80) {
        b =bb.get();
        result <<= 6;
        result |= b & 0x3F;
    }
    return -1; // Reached the end without decoding a full UTF-8 character
}
