private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit()) {
        int c = bb.get(i);
        if ((c & 0x80) == 0) {
            sb.append((char) c);
            i++;
        } else if ((c & 0xe0) == 0xC0) {
            sb.append((char) ((c & 0x1f) << 6 | bb.get(i + 1) & 0x3f));
            i += 2;
        } else if ((c & 0xf0) == 0xE0) {
            sb.append((char) ((c & 0x0f) << 12 | bb.get(i + 1) & 0x3f << 6 | bb.get(i + 2) & 0x3f));
            i += 3;
        } else if ((c & 0xf8) == 0xF0) {
            sb.append((char) ((c & 0x07) << 18 | bb.get(i + 1) & 0x3f << 12 | bb.get(i + 2) & 0x3f << 6 | bb.get(i + 3) & 0x3f));
            i += 4;
        } else {
            sb.append((char) (c & 0xff));
            i++;
        }
    }
    return i;
}
