@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Implementation to construct a complete bipartite graph
    // Example implementation using adjacency lists
    Set<V> nodes = resultMap.keySet();
    int n = nodes.size();
    List<V>[] graph = new List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }

    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V node = entry.getValue();
        String label = entry.getKey();
        for (V neighbor : nodes) {
            if (!neighbor.equals(node)) {
                graph[label.hashCode()].add(neighbor);
                graph[neighbor.hashCode()].add(label);
            }
        }
    }

    for (int i = 0; i < n; i++) {
        target.addEdge(nodes.get(i), nodes.get(i));
        for (V neighbor : graph[i]) {
            target.addEdge(nodes.get(i), neighbor);
        }
    }
}
