public static Class<?>[] resolveArguments(Type genericType,Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
    if (actualTypeArguments.length != targetType.getGenericSuperclass().getTypeParameters().length) {
        return null;
    }
    Type[] classArguments = ((ParameterizedType) targetType.getGenericSuperclass()).getActualTypeArguments();
    Type[] result = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < result.length; i++) {
        if (classArguments[i] instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) classArguments[i];
            if (wildcardType.getLowerBounds().length > 0) {
                result[i] = wildcardType.getLowerBounds()[0];
            } else {
                result[i] = wildcardType.getUpperBounds()[0];
            }
        } else {
            result[i] = classArguments[i];
        }
    }
    return result;
}
```

