import java.util.List;

public class TimeRangeUtil {
    private static final long FETCH_DATA_DURATION = 0; // Assume this value is defined in the class

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;

        while (currentStart < end - FETCH_DATA_DURATION) {
            long nextStart = currentStart + FETCH_DATA_DURATION;
            TimeRange range = new TimeRange(currentStart, nextStart);
            timeRanges.add(range);
            currentStart = nextStart;
