        long adjustedStart = start - (durationChunk - 1);
        long adjustedEnd = start + durationChunk - 1;
        result.add(new TimeRange(adjustedStart, adjustedEnd));
        while (adjustedStart < end) {
            adjustedStart += TIME_RANGE_CHUNK;
            adjustedEnd += TIME_RANGE_CHUNK;
            result.add(new TimeRange(adjustedStart, adjustedEnd));
        }
    } else {
        result.add(new TimeRange(start, end));
    }
    return result;
