    int i = index;
    while (i < index + len) {
        int b = str.charAt(i++);
        if ((b & 0xFC) == 0xC0) {
            if ((b & 0x1F) == 0) {
                System.err.println("Odd length 10-bit sequence at index " + i - 1);
                return -1;
            }
            size += 1;
        } else if ((b & 0xF8) == 0xE0) {
            if ((b & 0x3F) == 0 || (b & 0x3F) == 0x2F) {
                System.err.println("Odd length 12-bit sequence at index " + i - 1);
                return -1;
            }
            size += 2;
        } else if ((b & 0xF0) == 0xF0) {
            if ((b & 0x0F) == 0 || (b & 0x0F) == 0x1F) {
                System.err.println("Odd length 16-bit sequence at index " + i - 1);
                return -1;
            }
            size += 3;
        } else {
            System.err.println("Bad continuation byte at index " + i - 2);
            return -1;
        }
    }
    return size + (str.length() - index - len);
}
