public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws CharConversionException {
    if (str == null || lb == null) {
        throw new NullPointerException("str or lb cannot be null");
    }
    CharsetEncoder charsetEncoder = Charset.forName("UTF-8").newEncoder();
    charsetEncoder.onMalformedInput(CodingErrorAction.REPLACE);
    charsetEncoder.onUnmappableCharacter(CodingErrorAction.REPLACE);
    ByteBuffer encodedBuffer = ByteBuffer.allocate(session.binarySizeForString(str));
    charsetEncoder.encode(CharBuffer.wrap(str), encodedBuffer, true);
    lb.writeFrom(encodedBuffer);
    return lb;
}
