    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    StringBuilder pathBuilder = new StringBuilder();
    boolean ignoreLeadingSlash = true;

    for (int i = 0; i < u.getPath().length(); i++) {
        char c = u.getPath().charAt(i);
        if (ignoreLeadingSlash && c == '/') {
            ignoreLeadingSlash = false;
            continue;
        }
        pathBuilder.append(c);
    }

    String path = pathBuilder.toString();
    if (decode) {
        // Simulate decoding (e.g., replacing '+', '-', '_', etc. with spaces)
        path = path.replace("+", " ").replace("-", " ").replace("_", " ");
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}
