import java.net.URI;
import java.nio.file.ClosedPathException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) throws ClosedPathException {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    Path path = Paths.get(u.getPath());
    String[] segments = path.getNameString().split("/");

    for(String segment : segments) {
        if(decode) {
            segment = java.net.URLDecoder.decode(segment, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}
