    private File currentFile;
    private FileLister fileLister;

    public FileIterator(FileLister fileLister) {
        this.fileLister = fileLister;
        this.currentFile = fileLister.next();
    }

    @Override
    public InputStream next() throws IOException {
        if (currentFile != null) {
            return new FileInputStream(currentFile);
        }
        return null;
    }

    @Override
    public void close() throws IOException {
        fileLister.close();
        currentFile = null;
    }

    public static class FileLister {
        List<File> files;
        int index = 0;

        public FileLister.Lister(List<File> files) {
            this.files = files;
        }

        public File next() throws IOException {
            if (index < files.size()) {
                return files.get(index++);
            }
            return null;
        }

        public void close() throws IOException {
            // Assume close() method implementation is provided by the fileLister
