private long readRawVarint64() throws IOException {
    long result = 0;
    byte b = readByte();
    int shift;
    if (b >= 0) {
        result = b;
        while ((b >>>= 1) != 0) {
            result = (result << 1) | (b & 1);
        }
    } else {
        shift = -b & 7;
        do {
            b = readByte();
            result = (result << 8) | (b & 0xFF);
        } while (shift > 0);
    }
    return result;
}
