        switch (descriptor.charAt(0)) {
            case 'Z':
                System.out.println("Popping zero value");
                break;
            case 'B':
                System.out.println("Popping byte value");
                break;
            case 'C':
                System.out.println("Popping character value");
                break;
            case 'D':
                System.out.println("Popping double value");
                break;
            case 'F':
                System.out.println("Popping float value");
                break;
            case 'I':
                System.out.println("Popping integer value");
                break;
            case 'J':
                System.out.println("Popping long value");
                break;
            case 'S':
                System.out.println("Popping short value");
                break;
            case 'L':
                System.out.println("Popping primitive type");
                pop(descriptor.substring(1, descriptor.length() - 1));
                break;
            case '[':
                System.out.println("Popping array");
                pop(descriptor.substring(1));
                break;
            default:
                System.out.println("Exception: Unsupported type for popping from stack");
        }
    }
}
