        return 0;
    }
    int writtenSize = 0;
    OutByteBuffer singleBuffer = LinkedBuffer.single()
                                      . setData(node)
                                      . setDataType(node.getClass().getSimpleName());
    writtenSize += singleBuffer.write(out);
