```java
public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int size = 0;
    int length = node.getLength();
    byte[] buffer = node.getBuffer();
    for (int i = 0; i < length; i++) {
        int offset = i * 4;
        byte[] fixedLengthBuffer = ByteBuffer.allocate(4).putInt(length).array();
        out.write(fixedLengthBuffer, 0, 4);
        out.write(buffer, offset, 4);
        size += 4 + 4;
    }

    return size;
}
