public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Capacity must be a non-negative integer");
    }

    int cap = prunePrime(desiredCapacity, Integer.MAX_VALUE);
    return cap + 1;
}

private static int prunePrime(int cap, int maxPrime) {
    if (cap <= 1) {
        return maxPrime;
    }

    while (cap > 1) {
        if (_primes(cap) && (_isPrime((cap - 1)) || cap == 2)) {
            return cap;
        }
        cap--;
    }
    return maxPrime;
}

private static boolean _isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

private static boolean _primes(int num) {
    while (num % 10 == 0) {
        num /= 10;
    }
    switch (num) {
        case 11:
        case 13:
        case 17:
        case 19:
        case 23:
        case 29:
        case 31:
        case 37:
        case 41:
        case 43:
        case 47:
        case 53:
        case 59:
        case 61:
        case 67:
        case 71:
        case 73:
        case 79:
        case 83:
        case 89:
        case 97:
            return true;
    }
    return false;
}
