```java
public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1) {
        throw new IllegalArgumentException("desiredCapacity must be a positive integer");
    }
    if (desiredCapacity < 1000) {
        for (int i = 3; i <= desiredCapacity; i += 2) {
            if (isPrime(i)) return i;
        }
    } else {
       desiredCapacity = (int) Math.round(desiredCapacity * 1.111);
        int low = 7 + desiredCapacity / 9;
        if (low < ThreadLocalRandom.current().nextInt(16, 31)) low = ThreadLocalRandom.current().nextInt(7);
        while (true) {
            boolean isPrime = true;
            for (int i = 3; i <= Mathsqrt(low); i += 2) {
                if (low % i == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) return low;
            low += 2;
        }
    }
}
