public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        if (str.charAt(i) == '\\') {
            if (i < len - 1) {
                if (str.charAt(i + 1) == 'n') {
                    result.append('\n');
                    i++;
                } else if (str.charAt(i + 1) == 't') {
                    result.append('\t');
                    i++;
                } else if (str.charAt(i + 1) == 'r') {
                    result.append('\r');
                    i++;
                } else if (str.charAt(i + 1) == 'f') {
                    result.append('\f');
                    i++;
                } else if (str.charAt(i + 1) == '\\') {
                    result.append('\\');
                    i++;
                } else {
                    throw new IllegalArgumentException("Unsupported escape sequence: \\");
                }
            } else {
                throw new IllegalArgumentException("Unexpected end of escape sequence: \\");
            }
        } else {
            result.append(str.charAt(i));
        }
    }
    return result.toString();
}
