public static synchronized String unescapeJava(String str) throws Exception {
    if (str == null) return null;

    int len = str.length();

    StringBuffer b = new StringBuffer(len * 2);
    int state = 0;

    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);

        switch (state) {
            case 0:
                if (ch == '\\') {
                    state = 1;
                } else {
                    b.append(ch);
                }
                break;
            case 1:
                switch (ch) {
                    case '"':
                    case '\\':
                    case 'n':
                    case 'r':
                    case 't':
                        b.append(ch);
                        break;
                    default:
                        b.append("\\u").append(String.format("%04x", (int) ch));
                        state = 0;
                        break;
                }
                break;
        }
    }

    return b.toString();
}
