```java
static String[] toStringArray(Enumeration<String> enumeration) {
    if (enumeration == null) {
        return null;
    }

    int count = 0;
    while (enumeration.hasMoreElements()) {
        count++;
        enumeration.nextElement(); // Consume the element to move to the next one
    }

    String[] result = new String[count];
    enumeration = EnumerationUtilities.createArrayEnumeration(result);
    while (enumeration.hasMoreElements()) {
        enumeration.nextElement(); // Consume the elements from the Enumeration
    }

    int i = 0;
    while (enumeration.hasMoreElements()) {
        result[i] = enumeration.nextElement();
        i++;
    }

    return result;
}

private static final class EnumerationUtilities {
    public static Enumeration<String> createArrayEnumeration(String[] array) {
        return new Enumeration<String>() {
            private int index = 0;

            @Override
            public boolean hasMoreElements() {
                return index < array.length;
            }

            @Override
            public String nextElement() {
                if (index >= array.length) {
                    throw new NoSuchElementException();
                }
                return array[index++];
            }
        };
    }
}
```

