private String unescapeId(String input){
    int len = input.length();
    char[] arr = new char[len];
    Arrays.fill(arr, ' ');
    int pos = 0;
    int level = 0;
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '{') {
            if (level == 0) {
                pos = i + 1;
            }
            level++;
        } else if (c == '}') {
            level--;
            if (level == 0) {
                copy(input, pos, arr, pos, i - pos + 1);
                arr[pos] = '.'; // Replace } with .
                pos++;
            }
        } else {
            arr[pos++] = c;
        }
    }
    return new String(arr, 0, pos);
}
