    List<Integer> verticesInMinLabelBucket = new ArrayList<>();
    for (int i = 0; i < labels.size(); i++) {
        if (minLabel <= labels.get(i)) {
            verticesInMinLabelBucket.add(i);
        } else {
            break;
        }
    }

    // Move all these vertices to the bucket with label 0
    for (int i : verticesInMinLabelBucket) {
        int oldLabel = labels.get(i);
        int newLabel = 0;
        labels.set(i, newLabel);
        bucketsByLabel.get(oldLabel).remove(i);
        bucketsByLabel.get(newLabel).add(i);
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Update the labeling accordingly
    int newLabel = 1; // Assuming labels start from 1 for clarity
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, newLabel);
            newLabel++;
        }
    }
