    // Move all vertices from the bucket with label 0 to the bucket with label {@code minLabel}
    Map<Integer, Set<Integer>> bucketsByLabelNew = new HashMap<>();
    for (int label : labels) {
        if (label == 0) {
            bucketsByLabelNew.put(0, new HashSet<>());
            bucketsByLabelNew.get(0).addAll(bucketsByLabel.get(label));
        } else if (label == minLabel) {
