private Pair<List<Integer>, Long> computeSuffixSum(final List<Integer> bounds) {
List<Integer> suffixSumList = new ArrayList<>();
long totalSum = 0;

for (int i = bounds.size() - 1; i >= 0; i--) {
    if (i == bounds.size() - 1) {
        suffixSumList.add(bounds.get(i));
    } else {
        suffixSumList.add(suffixSumList.get(i) + bounds.get(i));
    }
    totalSum += bounds.get(i);
}

return new Pair<>(suffixSumList, totalSum);
}
