private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> sepList = new ArrayList<>();
    for (E edge : graph.edges()) {
        List<String> neighborhood = graph.getNeighborhood(edge.to());
        List<List<Pair<Integer,Integer>>> separatorList = new ArrayList<>();
        for (String node : neighborhood) {
            if (!node.equals(edge.to())) {
                List<Pair<Integer,Integer>> separator = new ArrayList<>();
                separator.add(Pair.with(node, edge.to()));
                separatorList.add(separator);
            }
        }
        sepList.addAll(separatorList);
    }
    return sepList;
}
