private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V v : vertices) {
        for (V u : vertices) {
            if (v.equals(u) || !graph.containsEdge(v, u)) {
                continue;
            }
            for (V w : vertices) {
                if (w.equals(v) || w.equals(u)) {
                    continue;
                }
                if (!graph.containsEdge(u, w)) {
                    return false;
                }
            }
        }
    }
    return true;
}
