    for (V v : graph.vertices) {
        if (!vertices.contains(v)) {
            return false; // If any vertex is not in the set, it's not a clique
        }
        for (V u : vertices) {
            if (graph.containsEdge(v, u) && u != v) {
                return false; // If any two vertices are connected, it's not a clique
