public static String applyRelativePath(String path, String relativePath) {
    int pathIndex = 0;
    int relativePathIndex = 0;

    // Find theSlash character after the last '/' in the path
    while (pathIndex < path.length() && path.charAt(pathIndex) != '/') {
        pathIndex++;
    }

    // Find theSlash character after the last '/' in the relative path
    while (relativePathIndex < relativePath.length() && relativePath.charAt(relativePathIndex) != '/') {
        relativePathIndex++;
    }

    // If no "/", append together and return
    if (relativePathIndex == relativePath.length()) {
        return path.substring(0, pathIndex) + relativePath;
    }

    // Find the starting point of a search for '/' in the path:
    while (pathIndex < path.length() && relativePath.charAt(0) != '/') {
        pathIndex++;
    }

    // Search for the next '/' of the same name in the relative path:
    while (relativePathIndex < relativePath.length() && relativePath.charAt(relativePathIndex) != '/' && relativePath.charAt(relativePathIndex) == path.charAt(pathIndex)) {
        relativePathIndex++;
        pathIndex++;
    }

    // Negate the path index if we found a slash:
    if (relativePathIndex < relativePath.length() && relativePath.charAt(relativePathIndex) == '/') {
        relativePathIndex--;
    }

    // Construct the concatenated string:
    return path.substring(0, pathIndex) + relativePath.substring(relativePathIndex);
}
