public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshotList = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line based on the format specified in the input
            // This is a simple example of parsing; actual parsing logic may vary depending on the actual file format
            String[] parts = line.split(",");
            long timestamp = Long.parseLong(parts[0]);
            double heapUsage = Double.parseDouble(parts[1]);
            ThreadSnapshot snap = new ThreadSnapshot(timestamp, heapUsage);
            snapshotList.add(snap);
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return snapshotList;
}
